module tornload

go 1.23

require modernc.org/sqlite v1.57.0
EOF
cat > main.go <<'EOF'
package main

import (
	"context"
	"fmt"
	"os"
	"sync"
	"sync/atomic"
)

type hdr struct {
	Epoch int `json:"epoch"`
}

type itemBody struct {
	Epoch int `json:"epoch"`
}

func build(epoch int) Record {
	h, _ := json.Marshal(hdr{Epoch: epoch})
	items := []Item{{Key: "a", Ordinal: 0, Payload: mustJSON(itemBody{epoch})}}
	if epoch%2 == 0 {
		items = append(items, Item{Key: "b", Ordinal: 1, Payload: mustJSON(itemBody{epoch})})
	}
	return Record{Kind: "k", Scope: "s", SchemaVersion: 1, Header: h, Items: items}
}

func main() {
	root, _ := os.MkdirTemp("", "torn")
	defer os.RemoveAll(root)
	store, err := Ensure(root)
	if err != nil { panic(err) }
	ctx := context.Background()
	if err := store.Save(ctx, build(0)); err != nil { panic(err) }

	var stop atomic.Bool
	var torn atomic.Int64
	var reads atomic.Int64
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		for i := 0; !stop.Load(); i++ {
			if err := store.Save(ctx, build(i%2)); err != nil { panic(err) }
		}
	}()
	for w := 0; w < 4; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for !stop.Load() {
				rec, err := store.Load(ctx, "k", "s")
				if err != nil { panic(err) }
				reads.Add(1)
				var h hdr
				json.Unmarshal(rec.Header, &h)
				set := map[string]int{}
				for _, it := range rec.Items {
					var b itemBody
					json.Unmarshal(it.Payload, &b)
					if b.Epoch != h.Epoch {
						torn.Add(1)
						return
					}
					set[it.Key] = b.Epoch
				}
				expectB := h.Epoch%2 == 0
				if _, has := set["b"]; has != expectB {
					torn.Add(1)
					return
				}
			}
		}()
	}
	wg.Wait()
	stop.Store(true)
	fmt.Printf("reads=%d torn=%d\n", reads.Load(), torn.Load())
}
EOF
